using System.Collections;
using System.Collections.Generic;
using System.Linq;
using Unity.Mathematics;
using UnityEngine;
using UnityEngine.Rendering;

public class NodeGraph
{
    #region Inputted data. All the other lists of nodes and links are pulled from this data and/or generated internally.
    /// <summary>
    /// The cards in this nodegraph. This is one of the two things that other objects add to this node graph.
    /// </summary>
    List<Card> cards = new();
    /// <summary>
    /// All the dynamic links between pins generated by the node graph, indexed by a unique ID value generated from a given pair of Card objects.
    /// These links are the ones that can be culled by the compute shader if they intersect with each other, or the cardLinks.
    /// </summary>
    Dictionary<ulong, NodeLink> pinLinks = new();
    #endregion

    /// <summary>
    /// Marks whether this NodeGraph has been built yet or not.
    /// </summary>
    private bool built;
    public bool IsReady
    {
        get
        {
            return built;
        }
    }

    #region Data buffers that require building
    /// <summary>
    /// A buffer that collects and stores the nodes. The nodegraph should never need to generate its own nodes.
    /// </summary>
    List<Node> nodesBuffer = new();
    /// <summary>
    /// A collection of all the static links generated by the cards. None of these should be generated by nodegraph.
    /// </summary>
    List<NodeLink> cardLinks = new();
    /// <summary>
    /// Invalid static links used purely for collision testing. These should not be considered links that pathways can use.
    /// </summary>
    List<NodeLink> invalidCardLinks = new();
    /// <summary>
    /// Links generated between nodes on different cards. These are not considered when checking for collisions, as they're just for pathfinding.
    /// However, they will have their collisions checked against just the cardLinks, and will destroy themselves if they collide with any of the card links.
    /// </summary>
    List<NodeLink> intercardLinks = new();
    #endregion

    #region Functions that allow inputting data into the graph
    /// <summary>
    /// Adds a given card object to this node graph
    /// </summary>
    public void AddCard(Card target)
    {
        cards.Add(target);
        built = false;
    }
    /// <summary>
    /// <para>Creates a link between two cards. This will ultimately put 1 pin on each of the cards, and create string between them.</para>
    /// <para>The order of the cards is irrelevant.</para>
    /// </summary>
    /// <param name="a">One of the cards that will be linked. The order is irrelevant.</param>
    /// <param name="b">The other card that will be linked. The order is irrelevant.</param>
    public void AddLink(Card a, Card b)
    {
        //Add the links on each of the cards (so they can generate the necessary pin nodes)
        a.AddLink(b);
        b.AddLink(a);

        //Generates the link object representing the link between the two cards.
        pinLinks.Add(Card.GetCardPairID(a, b), new NodeLink(
            a.GetLinkingNode(b), //Get the node on the "from" card that represents the pin that will be connected to "to"
            b.GetLinkingNode(a) //Get the node on the "to" card that represents the pin that will be connected to "from"
            ));

        built = false;
    }
    /// <summary>
    /// <para>Removes a link between cards.</para>
    /// <para>The order of the cards is irrelevant.</para>
    /// </summary>
    /// <param name="a">One of the cards that will be linked. The order is irrelevant.</param>
    /// <param name="b">The other card that will be linked. The order is irrelevant.</param>
    public void RemoveLink(Card a, Card b)
    {
        a.RemoveLink(b);
        b.RemoveLink(a);

        ulong code = Card.GetCardPairID(a, b);

        pinLinks[code].Release();
        pinLinks.Remove(code);

        built = false;
    }
    #endregion

    #region Building-related logic
    /// <summary>
    /// Tracks if the graph is already building itself, used to prevent the Build coroutine from running more than one at a time.
    /// </summary>
    private bool building;
    /// <summary>
    /// Builds the graph using the data. This needs to be ran every time a change is made to the graph.
    /// </summary>
    /// <returns></returns>
    public IEnumerator Build()
    {
        if (building || built) yield break;
        building = true;

        //Load the shaders if they haven't been loaded yet
        bool loadingShaders = intersectCheckShader == null || lengthShader == null;
        ResourceRequest loadIntersectShader = null;
        ResourceRequest loadLengthShader = null;
        if (loadingShaders)
        {
            loadIntersectShader = Resources.LoadAsync("LineSegmentIntersectCheck", typeof(ComputeShader));
            loadLengthShader = Resources.LoadAsync("LineSegmentLengthCalculator", typeof(ComputeShader));
        }

        //Clear previously buffered data
        nodesBuffer.Clear();
        static void ClearLinkList(List<NodeLink> target)
        {
            for (int i = target.Count - 1; i >= 0; i--)
            {
                target[i].Release();
            }
            target.Clear();
        }
        ClearLinkList(cardLinks);
        ClearLinkList(invalidCardLinks);
        ClearLinkList(intercardLinks);

        //Buffer nodes and links from the cards
        foreach (Card card in cards)
        {
            nodesBuffer.AddRange(card.CornerNodes);
            nodesBuffer.AddRange(card.PinNodes);
            cardLinks.AddRange(card.ValidCornerLinks);
            invalidCardLinks.AddRange(card.InvalidCornerLinks);
        }

        //Generate a bunch of links between nodes
        for (int a = 0; a < nodesBuffer.Count; a++)
        {
            //Initialising b to a will ensure we're only evaluating pairs that haven't been evaluated yet
            for (int b = a; b < nodesBuffer.Count; b++)
            {
                //If at least one of them are not a pin
                if (!(nodesBuffer[a].isPin && nodesBuffer[b].isPin))
                {
                    //If they originate from different cards
                    if (nodesBuffer[a].card != nodesBuffer[b].card)
                    {
                        intercardLinks.Add(new NodeLink(nodesBuffer[a], nodesBuffer[b]));
                    }
                }
            }
        }

        //Assign the loaded shaders if they were loaded
        if (loadingShaders)
        {
            if (!loadIntersectShader.isDone)
            {
                yield return loadIntersectShader;
            }
            intersectCheckShader = loadIntersectShader.asset as ComputeShader;
            if (!loadLengthShader.isDone)
            {
                yield return loadLengthShader;
            }
            lengthShader = loadLengthShader.asset as ComputeShader;
        }

        //Use compute shaders to cull intersecting links, and calculate their lengths. Moved this to another coroutine for the sake of organisation because it is a LOT of code.
        yield return CullIntersectsAndGetLength();

        building = false;
        built = true;
    }
    /// <summary>
    /// We load the shaders once and buffer them for use later
    /// </summary>
    private ComputeShader intersectCheckShader, lengthShader;
    private ComputeBuffer linkBuffer, hitBuffer;
    IEnumerator CullIntersectsAndGetLength()
    {
        //Ensure we're only doing this one at a time.
        if (linkBuffer != null || hitBuffer != null) yield break;

        #region Setup
        //Establish some integer values repeatedly used, so we don't have to recalculate every time.
        int offset = cardLinks.Count + invalidCardLinks.Count; //The point that splits the 2nd and 3rd array that compose Link array. This will make sense when you learn what Link Array is, next to its definition.
        int total = offset + intercardLinks.Count; //The total amount of elements that link array will have.
        int totalIterations = offset * (total - offset); //How many threads will need to be created to compute all the data.

        //Link array a giant array of float4s representing the values shaders will use for their math.
        //The array is more like a composite of 3 arrays, in the following order:
        //1. The links that go around the perimeter of the cards
        //2. The fake links around the permiter of the cards that don't actually exist, but are used for collision checking anyways.
        //3. The huge composite of links generated between nodes.
        //The float4 is just (A.x, A.y, B.x, B.y) where a given link is represented by line segment AB. NodeLink already defines how it should be typecasted into a float4.
        float4[] linkArray = new float4[total];
        //Hits array maps directly to just the 3rd part of link array, and is used to store if any collisions were detected between the first 2 parts and a given element in the 3rd part.
        int[] hitsArray = new int[intercardLinks.Count];

        //Populate link array, based on the layout which I explained in the comments next to its definition.
        cardLinks.Select(link => (float4)link).ToArray().CopyTo(linkArray, 0);
        invalidCardLinks.Select(link => (float4)link).ToArray().CopyTo(linkArray, cardLinks.Count);
        intercardLinks.Select(link => (float4)link).ToArray().CopyTo(linkArray, offset);

        //Create the buffers that represent the space in GPU memory the shaders will use
        linkBuffer = new ComputeBuffer(linkArray.Length, sizeof(float) * 4);
        hitBuffer = new ComputeBuffer(hitsArray.Length, sizeof(int));
        //and set their data
        linkBuffer.SetData(linkArray);
        hitBuffer.SetData(hitsArray);
        #endregion

        #region Intersection compute shader
        //Assign the values to the shader
        intersectCheckShader.SetInt("offset", offset);
        intersectCheckShader.SetInt("total", total);
        intersectCheckShader.SetBuffer(0, "links", linkBuffer);
        intersectCheckShader.SetBuffer(0, "hits", hitBuffer);
        //Run the shader, with as many thread groups as needed to ensure complete coverage of all the line segments.
        intersectCheckShader.Dispatch(0, Mathf.CeilToInt(totalIterations / 64f), 1, 1);

        //Prepare an asynchronous data readback, and wait until the shader is done + the data has been read back
        AsyncGPUReadbackRequest hitRequest = AsyncGPUReadback.Request(hitBuffer);
        yield return new WaitUntil(() => hitRequest.done || hitRequest.hasError);
        if (hitRequest.hasError) Debug.LogError("Encountered error attempting to fetch hit results!");
        hitRequest.GetData<int>().CopyTo(hitsArray);

        //We're going to rewrite data back into the links array buffer for the next shader, so memory doesn't have to be reallocated. We still have to rewrite to it though.
        float4[] linksToFindLength = new float4[intercardLinks.Count];

        int culledSize = 0; //How many links we've removed so far
        int refilledCounter = 0; //How many links we've kept so far
        //Iterating backwards through every hit
        for (int i = hitsArray.Length - 1; i >= 0; i--)
        {
            //If there was any intersections on this link
            if (hitsArray[i] == 1)
            {
                //Release and remove the link
                intercardLinks[i].Release();
                intercardLinks.RemoveAt(i);
                culledSize++;
            }
            else
            {
                //Populate the new array with the data from this link
                linksToFindLength[refilledCounter] = linkArray[i + offset];
                refilledCounter++;
            }
        }

        //Release the hit buffer data and get rid of it
        hitBuffer.Release();
        hitBuffer = null;
        #endregion

        #region Length compute shader
        //Assign the new link array data to the buffer we used for the last shader
        linkBuffer.SetData(linksToFindLength, 0, 0, refilledCounter);

        //Assign that buffer to the length shader, and dispatch it with as little thread groups needed to ensure complete coverage.
        lengthShader.SetBuffer(0, "links", linkBuffer);
        lengthShader.Dispatch(0, Mathf.CeilToInt(refilledCounter / 64f), 1, 1);

        //Prepare an asynchronous data readback, and wait until the shader is done + the data has been read back
        AsyncGPUReadbackRequest lengthRequest = AsyncGPUReadback.Request(linkBuffer);
        yield return new WaitUntil(() => lengthRequest.done || lengthRequest.hasError);
        if (lengthRequest.hasError) Debug.LogError("Encountered error attempting to fetch link distance results!");
        linksToFindLength = lengthRequest.GetData<float4>().ToArray();

        //Feed the calculated distance values into their respective links.
        for (int i = 0; i < refilledCounter; i++)
        {
            //We actually filled the data into the length shader backwards, so here we're inverting the order.
            intercardLinks[refilledCounter - i - 1].distance = linksToFindLength[i].x;

            //This is just used for the render function, which will be removed later.
            debugShortest = Mathf.Min(debugShortest, linksToFindLength[i].x);
            debugLongest = Mathf.Max(debugLongest, linksToFindLength[i].x);
        }

        //Free the link buffer's resources and null its value.
        linkBuffer.Release();
        linkBuffer = null;
        #endregion
    }
    #endregion

    #region Debug functions that will be removed
    //Everything with "debug" in front of it is temporary and will be removed before the end of the project
    private float debugShortest = float.MaxValue;
    private float debugLongest = float.MinValue;
    public void DebugRender(bool renderCards, bool renderPins, bool renderIntercards, Path withPath)
    {
        if (renderCards)
        {
            foreach (NodeLink cardLink in cardLinks)
            {
                Debug.DrawLine(cardLink.StartPos, cardLink.EndPos, Color.blue);
            }
        }
        if (renderPins)
        {
            foreach (NodeLink pinLink in pinLinks.Values)
            {
                Debug.DrawLine(pinLink.StartPos, pinLink.EndPos, Color.cyan);
            }
        }
        if (renderIntercards)
        {
            foreach (NodeLink intercardLink in intercardLinks)
            {
                Debug.DrawLine(intercardLink.StartPos, intercardLink.EndPos, Color.Lerp(Color.green, Color.red, (intercardLink.distance - debugShortest) / debugLongest));
            }
        }
        if (withPath != null)
        {
            foreach (PointedNodeLink link in withPath.Links)
            {
                Debug.DrawLine(link.Link.StartPos, link.Link.EndPos, Color.white);
            }
        }
    }
#if UNITY_EDITOR
    public void DebugRenderLabels()
    {
        foreach (Node node in nodesBuffer)
        {
            node.Debug_DrawID();
        }
    }
#endif
    public Vector3[] DebugNodePositions()
    {
        Vector3[] allPos = new Vector3[nodesBuffer.Count];

        for (int i = 0; i < nodesBuffer.Count; i++)
        {
            allPos[i] = nodesBuffer[i].position;
        }

        return allPos;
    }
    public Node DebugRandomNode(bool bePin)
    {
        Node random = nodesBuffer[UnityEngine.Random.Range(0, nodesBuffer.Count - 1)];
        while (random.isPin != bePin)
        {
            random = nodesBuffer[UnityEngine.Random.Range(0, nodesBuffer.Count - 1)];
        }
        return random;
    }
    public Node DebugGetNode(int ID, bool fallbackBePin)
    {
        foreach (Node node in nodesBuffer)
        {
            if (node.ID == ID)
            {
                return node;
            }
        }
        return DebugRandomNode(fallbackBePin);
    }
    public void DebugClearAllNodeMessage()
    {
        foreach (Node node in nodesBuffer)
        {
            node.debug_customMessage = "";
        }
    }
    #endregion
}